  cilindrada = (parsed.cilindrada || '').toString().trim();
  if (esCompatibilidad) restoMensaje = (parsed.resto_mensaje || '').toString().trim();
} catch (e) {}

const escapar = (s) => s.replace(/'/g, "''");

