      kitId = id;
    } else {
      tipo = 'ninguno'; // nunca confiar en un id fuera de la lista cerrada
    }
  }

  if (tipo === 'candidatos') {
    const cands = (Array.isArray(parsed.candidatos) ? parsed.candidatos : [])
      .map((c) => ({ kit_id: Number(c && c.kit_id), nombre: ((c && c.nombre) || '').toString() }))
      .filter((c) => idsValidos.has(c.kit_id));
    if (cands.length >= 2 && cands.length <= 3) {
      candidatos = cands;
    } else {
      tipo = 'ninguno'; // no vino bien formado, no arriesgar una repregunta rota
    }
  }
} catch (e) {}

const kitNombre = kitId !== null ? (kitsById.get(kitId)?.nombre || '') : '';

if (tipo === 'kit_confiado' && !mensaje) {
  mensaje = `Dale, es sobre ${kitNombre}, ¿no?`;
}
if (tipo === 'candidatos' && !mensaje) {
  mensaje = `¿Te referís a ${candidatos.map((c) => c.nombre).join(' o a ')}?`;
}

return [{ json: { tipo, kit_id: kitId, kit_nombre: kitNombre, candidatos, mensaje } }];

let mensaje = ($json.output || '').toString().trim();
if (!mensaje) {
  const cil = ($('Parsear Pregunta Compatibilidad').item.json.cilindrada || '').toString().trim();
  mensaje = cil ? `Para una ${cil}, que marca y modelo es?` : 'Que marca y modelo es tu moto?';
}
return [{ json: { mensaje } }];
